      if (tid == 0) { while (ld_acquire(ctr) == 0u) { } }
      __syncthreads();
      if (tid < 384) {
        const float v = s_ssp[tid] + s_ssp[384 + tid] + s_ssp[768 + tid] + s_ssp[1152 + tid];
